      '<div data-vim-reticle-corner="top-left"></div>',
      '<div data-vim-reticle-corner="top-right"></div>',
      '<div data-vim-reticle-corner="bottom-left"></div>',
      '<div data-vim-reticle-corner="bottom-right"></div>',
